SELECT * FROM (SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Heat Treatment Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='HT' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Inspection Failed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='IF' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Inspection Passed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='IP') ORDER BY case_id,timestamp,event_id;
